const icons = {
  mark:'<path d="m7 3-5 18h6l5-18H7Zm10 0-5 18h5l5-18h-5Z" fill="currentColor" stroke="none"/>',
  car:'<path d="m5 7 2-4h10l2 4M3 10l2-3h14l2 3v8H3v-8Zm3 8v3m12-3v3M3 13h18M6 10h1m10 0h1"/>',
  compare:'<rect x="3" y="4" width="7" height="16" rx="1"/><rect x="14" y="4" width="7" height="16" rx="1"/><path d="M6 8h1m10 0h1M6 12h1m10 0h1"/>',
  list:'<path d="m3 6 1 1 2-2m3 1h12M3 12h3m3 0h12M3 18h3m3 0h12"/>',
  wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 7V4a1 1 0 0 1 1-1h13v2m4 6h-6v5h6m-3-2.5h.01"/>',
  down:'<path d="m7 10 5 5 5-5"/>',right:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',
  edit:'<path d="m14 5 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  star:'<path d="m12 3 2.7 5.6 6.2.9-4.5 4.4 1.1 6.1-5.5-2.9L6.5 20l1-6.1L3 9.5l6.2-.9L12 3Z"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',file:'<path d="M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 13h8m-8 4h6"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand = `<span class="brand">${icon('mark')}<span>steervo<span class="brand-dot">.</span></span></span>`;
const directions = {
  workspace:{letter:'A',name:'Studio',summary:'Fahrzeuge im Fokus. Erfassen und Vergleichen bleiben direkt verbunden.',description:'Elektrisches Blau, eine kompakte Navigation und eine grosse Fahrzeugbühne. Rechts stehen deine Anforderungen; die Auswahl bleibt immer griffbereit.',best:'Schneller Wechsel zwischen Recherche und Vergleich.',tradeoff:'Bilder nehmen bewusst Raum ein.'},
  dossier:{letter:'B',name:'Canvas',summary:'Eine offene Fahrzeugakte. Apricot, Aubergine und Bearbeitung direkt im Inhalt.',description:'Ein grosszügiger, warmer Entwurf mit horizontaler Navigation. Fahrzeug, persönliche Eindrücke und Anforderungen bilden eine zusammenhängende Seite.',best:'In Ruhe recherchieren, Eindrücke festhalten.',tradeoff:'Mehr Platz und längere Seiten pro Fahrzeug.'},
  matrix:{letter:'C',name:'Focus',summary:'Der Vergleich als Arbeitsfläche. Dunkle Flächen, klare Werte und direkte Bearbeitung.',description:'Ein dunkler Vergleichsbereich mit visueller Fahrzeugauswahl. Unterschiede und offene Angaben führen durch die Entscheidung.',best:'Eine engere Auswahl gründlich gegeneinander prüfen.',tradeoff:'Auf dem Handy wird der Vergleich seitlich gescrollt.'}
};
const initialCars = [
{id:'enyaq',name:'Škoda Enyaq',trim:'85 · Selection',year:'2025',mileage:'12’400',status:'Favorit',note:'Gutes Raumgefühl bei der Probefahrt. Anhängerkupplung und Liefertermin noch mit dem Anbieter klären.',specs:['4’658 mm','1’879 mm','5','77 kWh'],price:'49’800'},
{id:'id7',name:'VW ID.7 Tourer',trim:'Pro · Business',year:'2025',mileage:'8’600',status:'In Auswahl',note:'Ruhig auf der Autobahn. Die Länge nochmals in der Garage prüfen.',specs:['4’961 mm','1’862 mm','5','77 kWh'],price:'53’400'},
{id:'i5',name:'BMW i5 Touring',trim:'eDrive40 · Sport',year:'2024',mileage:'19’200',status:'In Auswahl',note:'Sehr komfortabel. Höherer Kaufpreis, noch keine aktuelle Offerte erhalten.',specs:['5’060 mm','1’900 mm','5','81 kWh'],price:null}
];
const criteria = [
{id:'boot',name:'Kofferraum',type:'number',unit:'l',threshold:550,priority:'Muss',group:'Alltag & Platz',hint:'Mindestens 550 l'},
{id:'tow',name:'Anhängerkupplung',type:'boolean',priority:'Muss',group:'Alltag & Platz',hint:'Vorhanden oder nachrüstbar'},
{id:'range',name:'Reichweite im Winter',type:'number',unit:'km',threshold:350,priority:'Muss',group:'Unterwegs',hint:'Mindestens 350 km'},
{id:'charge',name:'Ladezeit 20–80 %',type:'number',unit:'min',threshold:30,max:true,priority:'Gewünscht',group:'Unterwegs',hint:'Höchstens 30 min'},
{id:'comfort',name:'Sitzkomfort',type:'rating',priority:'Gewünscht',group:'Unterwegs',hint:'Persönliche Einschätzung · 1–5'}
];
const initialValues = {
enyaq:{boot:{value:'585',source:'Herstellerangabe'},tow:{value:'',source:'Noch offen'},range:{value:'340',source:'Eigene Recherche'},charge:{value:'28',source:'Herstellerangabe'},comfort:{value:'4',source:'Probefahrt'}},
id7:{boot:{value:'605',source:'Herstellerangabe'},tow:{value:'Ja',source:'Offerte'},range:{value:'380',source:'Eigene Recherche'},charge:{value:'28',source:'Herstellerangabe'},comfort:{value:'5',source:'Probefahrt'}},
i5:{boot:{value:'570',source:'Herstellerangabe'},tow:{value:'Nein',source:'Offerte'},range:{value:'',source:'Noch offen'},charge:{value:'30',source:'Herstellerangabe'},comfort:{value:'4',source:'Probefahrt'}}
};
const params = new URLSearchParams(location.search);
const concept = Object.hasOwn(directions,params.get('concept')) ? params.get('concept') : null;
const embedded = params.has('embed');
let stored;
try{stored=JSON.parse(sessionStorage.getItem('steervo-design-demo-v2')||'null')}catch{}
let cars=stored?.cars||structuredClone(initialCars),values=stored?.values||structuredClone(initialValues);
let state={view:params.get('view')==='compare'||concept==='matrix'?'compare':'capture',car:cars[0].id,second:cars[1].id,tab:'criteria',filter:'all',compareTab:'criteria',editor:null,offer:false};
let lastFocus,toastTimer;
const app=document.querySelector('#app');
const carById=id=>cars.find(c=>c.id===id);
const getValue=(car,criterion)=>values[car]?.[criterion]||{value:'',source:'Noch offen',notes:''};
const btn=(text,action,extra='',kind='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${text}</button>`;
function persist(){try{sessionStorage.setItem('steervo-design-demo-v2',JSON.stringify({cars,values}))}catch{}}
function statusFor(cr,value){if(value==='')return{label:'Noch offen',class:'open'};if(cr.type==='rating')return{label:'Persönlich',class:'neutral'};const met=cr.type==='boolean'?value==='Ja':cr.max?Number(value)<=cr.threshold:Number(value)>=cr.threshold;return {label:met?'Erfüllt':'Nicht erfüllt',class:met?'':'bad'};}
function statusTag(cr,value){const s=statusFor(cr,value);return `<span class="status ${s.class}">${s.class===''?icon('check'):''}${s.label}</span>`;}
function priority(cr){return `<span class="pill ${cr.priority==='Muss'?'required':''}">${cr.priority}</span>`;}
function valueText(cr,value){return value===''?'Noch offen':`${esc(value)}${cr.type==='rating'?' / 5':cr.unit?' '+cr.unit:''}`;}
function openCount(id){return criteria.filter(c=>getValue(id,c.id).value==='').length;}
function announce(message){document.querySelector('#announcement').textContent=message;}
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.innerHTML=icon('check')+esc(message);document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200);}
function reviewBar(){return `<div class="review-bar"><a href="./">${icon('left')} Alle Entwürfe</a><nav class="switcher" aria-label="Designrichtung">${Object.entries(directions).map(([key,d])=>`<a href="?concept=${key}" class="${key===concept?'active':''}" ${key===concept?'aria-current="page"':''}>${d.letter}<span>${d.name}</span></a>`).join('')}</nav><span class="demo-label">Entwurfsrunde 2 · Beispieldaten</span></div>`;}
function gallery(){document.documentElement.lang='de';app.innerHTML=`<main id="main" class="gallery" tabindex="-1"><div class="gallery-top">${brand}<span class="gallery-round">Entwurfsrunde 2</span></div><div class="gallery-heading"><h1>Steervo neu denken.</h1><p>Drei eigenständige Richtungen für deine Fahrzeugentscheidung.<br>Erfassen, vergleichen, weiterdenken. Direkt ausprobieren.</p></div><div class="gallery-options">${Object.entries(directions).map(([key,d])=>`<article class="direction ${key}"><div class="direction-title"><h2><span>${d.letter}</span>${d.name}</h2><a class="open-direction" href="?concept=${key}" aria-label="${d.name} öffnen">${icon('arrow')}</a></div><a class="direction-preview" href="?concept=${key}" aria-label="${d.name} ausprobieren"><iframe src="?concept=${key}&embed=1" title="Vorschau ${d.name}" tabindex="-1" loading="eager" aria-hidden="true"></iframe></a><p>${d.description}</p><a class="button primary" href="?concept=${key}">${d.name} ausprobieren ${icon('arrow')}</a><dl><div><dt>Stärke </dt><dd>${d.best}</dd></div><div><dt>Abwägung </dt><dd>${d.tradeoff}</dd></div></dl></article>`).join('')}</div><footer class="gallery-footer"><span>Eine Angabe bearbeiten, speichern und im Vergleich wiederfinden.</span><span>Illustrative Bilder und Beispieldaten. <button class="plain-link" data-action="reset">Demo zurücksetzen</button></span></footer></main>`;}
function navigation(){return [{key:'capture',label:'Garage',icon:'car'},{key:'compare',label:'Vergleich',icon:'compare'},{key:'criteria',label:'Kriterien',icon:'list'},{key:'finance',label:'Offerten',icon:'wallet'}].map(n=>`<button data-action="navigate" data-view="${n.key}" class="${state.view===n.key?'active':''}" ${state.view===n.key?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span></button>`).join('');}
function context(){return `<header class="context-bar"><div class="crumbs"><strong>Familienauto 2026</strong>${icon('right')}<span>${{capture:'Deine Garage',compare:'Dein Vergleich',criteria:'Deine Kriterien',finance:'Deine Offerten'}[state.view]}</span></div><span class="context-count">${cars.length} Autos in deiner Auswahl</span></header>`;}
function sidebar(){return `<aside class="sidebar"><a class="rail-brand" href="?concept=workspace" aria-label="Steervo Studio">${icon('mark')}</a><nav class="side-nav" aria-label="Evaluation">${navigation()}</nav><div class="sidebar-bottom"><span class="avatar" aria-label="Dein Bereich">DU</span></div></aside>`;}
function topNav(){return `<header class="top-navigation">${brand}<nav aria-label="Evaluation">${navigation()}</nav><span class="avatar" aria-label="Dein persönlicher Bereich">DU</span></header>`;}
function candidateList(){return `<aside class="candidate-list" aria-label="Fahrzeuge"><div class="candidate-list-heading"><span>Deine Autos <span class="muted">${cars.length}</span></span><button class="icon-button" data-action="add" aria-label="Auto hinzufügen">${icon('plus')}</button></div>${cars.map(c=>`<button class="candidate-link ${c.id===state.car?'active':''}" data-action="select-car" data-car="${c.id}" ${c.id===state.car?'aria-current="true"':''}><strong>${esc(c.name)}</strong><span class="trim">${esc(c.trim)}</span><span class="candidate-meta"><span class="status ${c.status==='Favorit'?'':'neutral'}">${c.status==='Favorit'?icon('star'):''}${esc(c.status)}</span><span>${openCount(c.id)} offen</span></span></button>`).join('')}<p class="list-footer">Alle Angaben an einem Ort.<br>Vergleiche, sobald du bereit bist.</p></aside>`;}
function vehicleImage(id,cls){return ['enyaq','id7','i5'].includes(id)?`<img class="${cls}" src="assets/${id}.jpg" alt="Illustratives Modellbild ${esc(carById(id).name)}" decoding="async">`:`<div class="${cls} image-empty">${icon('car')}<span>Noch kein Fahrzeugbild</span></div>`;}
function candidateRibbon(){return `<div class="shortlist"><div class="candidate-ribbon" aria-label="Fahrzeuge">${cars.map(c=>`<button class="candidate-chip ${c.id===state.car?'active':''}" data-action="select-car" data-car="${c.id}" ${c.id===state.car?'aria-current="true"':''}>${vehicleImage(c.id,'thumbnail')}<span><strong>${esc(c.name)}</strong><small>${c.status==='Favorit'?'Dein Favorit':openCount(c.id)+' Angaben offen'}</small></span>${c.id===state.car?icon('check'):''}</button>`).join('')}</div>${btn(icon('plus')+' Auto hinzufügen','add')}</div>`;}
function tabs(){return `<nav class="tabs" aria-label="Fahrzeugdetails">${[{key:'criteria',label:'Kriterien'},{key:'specs',label:'Technische Daten'},{key:'offers',label:'Offerten'},{key:'notes',label:'Notizen'}].map(t=>`<button class="${state.tab===t.key?'active':''}" data-action="tab" data-tab="${t.key}" ${state.tab===t.key?'aria-current="page"':''}>${t.label}</button>`).join('')}</nav>`;}
function filters(compare=false){return `<div class="filter-row" aria-label="Kriterien filtern">${[{key:'all',label:'Alle'},...(compare?[{key:'different',label:'Unterschiede'}]:[]),{key:'required',label:'Muss'},{key:'open',label:'Offen'}].map(f=>`<button class="filter-button ${state.filter===f.key?'active':''}" aria-pressed="${state.filter===f.key}" data-action="filter" data-filter="${f.key}">${f.label}</button>`).join('')}</div>`;}
function filtered(compare=false){return criteria.filter(cr=>state.filter==='all'||state.filter==='required'&&cr.priority==='Muss'||state.filter==='open'&&(getValue(state.car,cr.id).value===''||compare&&getValue(state.second,cr.id).value==='')||state.filter==='different'&&getValue(state.car,cr.id).value!==getValue(state.second,cr.id).value);}
function assessmentRow(cr){const value=getValue(state.car,cr.id);return `<button class="assessment-row" data-action="edit" data-car="${state.car}" data-criterion="${cr.id}" aria-label="${esc(cr.name)} bearbeiten, ${valueText(cr,value.value)}"><span class="criterion-title">${cr.name}${priority(cr)}<small>${cr.hint}</small></span><span class="assessment-value">${valueText(cr,value.value)}<small>${esc(value.source)}</small><small class="mobile-state ${statusFor(cr,value.value).class}">${statusFor(cr,value.value).label}</small></span>${statusTag(cr,value.value)}${icon('edit').replace('class="icon"','class="icon edit-hint"')}</button>${concept==='dossier'&&state.editor?.criterion===cr.id?editorForm(true):''}`;}
function assessments(){const rows=filtered();return `<div class="section-toolbar"><div><h3>Deine Anforderungen</h3><p>Direkt auswählen und ergänzen.</p></div>${filters()}</div>${[...new Set(rows.map(c=>c.group))].map(group=>`<section><div class="assessment-heading"><strong>${group}</strong><span>${rows.filter(c=>c.group===group).length} Kriterien</span></div>${rows.filter(c=>c.group===group).map(assessmentRow).join('')}</section>`).join('')||'<div class="empty"><h3>Hier ist alles geklärt.</h3><p>Mit diesem Filter sind keine Kriterien offen.</p><button class="button text" data-action="filter" data-filter="all">Alle Kriterien anzeigen</button></div>'}<div class="assessment-summary"><span>${criteria.length-openCount(state.car)} von ${criteria.length} Angaben erfasst</span><span>Keine automatische Gesamtnote</span></div>`;}
function specs(){const car=carById(state.car);return `<div class="section-toolbar"><div><h3>Technische Daten</h3><p>Fakten zum Auto, unabhängig von deinen Kriterien.</p></div>${btn(icon('edit')+' Bearbeiten','edit-specs')}</div><div class="secondary-grid">${[['Abmessungen & Platz',['Länge','Breite ohne Spiegel','Sitzplätze'],car.specs.slice(0,3)],['Fahrzeug & Antrieb',['Erstzulassung','Kilometerstand','Batterie (netto)'],[car.year,car.mileage+' km',car.specs[3]]]].map(([title,labels,vals])=>`<section class="detail-section"><h3>${title}</h3><dl class="data-list">${labels.map((label,i)=>`<div><dt>${label}</dt><dd>${esc(vals[i]||'Noch offen')}</dd></div>`).join('')}</dl></section>`).join('')}</div>`;}
function offers(){const car=carById(state.car);return `<div class="offer-heading"><h3>Offerten für ${esc(car.name)}</h3><span class="demo-note">Beispielofferte</span></div>${car.price?`<div class="offer-row"><div><h3>Autohaus am See</h3><p>Kauf · CHF · Version 2</p><p><span class="status">Aktuell</span> <span class="demo-note">Stand 10.11.2026</span></p></div><div class="offer-price">CHF ${esc(car.price)}<small>Bestätigter Gesamtpreis · Beispieldaten</small>${btn((state.offer?'Details schliessen':'Offerte ansehen')+' '+icon('right'),'offer','', 'text')}</div></div>${state.offer?'<div class="offer-detail"><p><strong>Version 2</strong> · Kaufpreis inklusive Zubehör und Bereitstellung.</p><p>Die Änderungen zur ersten Version sowie Dokumente würden hier gemeinsam erscheinen.</p><p class="demo-note">Layoutvorschlag für Offerten. Versionierung und Dokumente bleiben Teil der bestehenden Anwendung.</p></div>':''}`:'<div class="empty"><h3>Noch keine Offerte</h3><p>Für dieses Beispielauto liegt kein Angebot vor.</p></div>'}<p class="record-bottom-note">Offerten behalten ihre Versionen und Dokumente. Kosten und Rechenszenarien werden in einer nächsten Ausarbeitung in dieselbe Struktur eingeordnet.</p>`;}
function notes(){return `<section class="detail-section"><div class="section-toolbar"><h3>Deine Notizen</h3>${btn(icon('edit')+' Bearbeiten','edit-notes')}</div><p class="notes-copy">${esc(carById(state.car).note||'Noch keine Notiz erfasst.')}</p><p class="record-bottom-note">Notizen zu einzelnen Bewertungen findest du direkt beim jeweiligen Kriterium.</p></section>`;}
function dossierAside(){const car=carById(state.car);return `<aside class="dossier-aside"><section class="aside-section"><h3>Dein Eindruck</h3><p>${esc(car.note||'Noch keine Notiz erfasst.')}</p>${btn('Notiz bearbeiten','edit-notes','','text')}</section><section class="aside-section"><h3>Als Nächstes klären</h3><p>${openCount(car.id)?criteria.filter(c=>getValue(car.id,c.id).value==='').map(c=>c.name).join(', '):'Alle Kriterien sind erfasst. Prüfe jetzt die Unterschiede im Vergleich.'}</p>${btn('Im Vergleich ansehen '+icon('arrow'),'navigate','data-view="compare"','','')}</section></aside>`;}
function record(){const car=carById(state.car);const content={criteria:assessments,specs,offers,notes}[state.tab]();return `<section class="record"><div class="vehicle-stage"><div class="vehicle-title"><span class="status">${car.status==='Favorit'?icon('star'):''}${esc(car.status)}</span><h1>${esc(car.name)}</h1><p class="record-subtitle">${esc(car.trim)}</p></div><div class="vehicle-image-wrap">${vehicleImage(car.id,'vehicle-image')}<span class="image-caption">Illustratives Modellbild</span></div><div class="vehicle-facts"><span>${esc(car.year)}<small>Erstzulassung</small></span><span>${esc(car.mileage)} km<small>Kilometerstand</small></span><span>${esc(car.specs[3]||'Offen')}<small>Batterie netto</small></span></div><div class="row-actions">${btn(icon('edit')+' Stammdaten','edit-car')}${btn('Vergleichen '+icon('arrow'),'navigate','data-view="compare"','primary')}</div></div><div class="record-content">${tabs()}${concept==='dossier'?`<div class="dossier-content"><div>${content}</div>${dossierAside()}</div>`:content}${state.tab==='criteria'?'<p class="record-bottom-note">Deine Kriterien, deine Entscheidung. Ein verfehltes Muss schliesst kein Auto automatisch aus.</p>':''}</div></section>`;}
function capture(){return `<div class="capture-layout">${candidateRibbon()}${record()}</div>`;}
function compareSelect(id,side){return `<div class="compare-visual">${vehicleImage(id,'compare-image')}<span class="status">${esc(carById(id).status)}</span></div><label class="compare-candidate" for="compare-${side}">${side==='first'?'Erstes':'Zweites'} Auto</label><select id="compare-${side}" class="candidate-select" data-compare="${side}" aria-label="${side==='first'?'Erstes':'Zweites'} Auto">${cars.filter(c=>c.id!==(side==='first'?state.second:state.car)).map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="compare-trim">${esc(carById(id).trim)}</span>`;}
function comparisonRows(){if(state.compareTab==='specs')return ['Länge','Breite ohne Spiegel','Sitzplätze','Batterie (netto)'].map((label,i)=>`<tr><th scope="row">${label}</th>${[state.car,state.second].map(id=>`<td class="static-cell">${esc(carById(id).specs[i]||'Noch offen')}</td>`).join('')}</tr>`).join('');const rows=filtered(true);return [...new Set(rows.map(c=>c.group))].map(group=>`<tr class="group-label"><th colspan="3">${group}</th></tr>${rows.filter(c=>c.group===group).map(cr=>`<tr><th scope="row">${cr.name} ${priority(cr)}<small>${cr.hint}</small></th>${[state.car,state.second].map(id=>{const val=getValue(id,cr.id),s=statusFor(cr,val.value);return `<td><button class="cell-edit ${s.class}" data-action="edit" data-car="${id}" data-criterion="${cr.id}" aria-label="${esc(cr.name)} für ${esc(carById(id).name)} bearbeiten"><span><span class="value">${valueText(cr,val.value)}</span><small>${s.label} · ${esc(val.source)}</small></span>${icon('edit')}</button></td>`}).join('')}</tr>${concept==='dossier'&&state.editor?.criterion===cr.id?`<tr class="comparison-editor-row"><td colspan="3">${editorForm(true)}</td></tr>`:''}`).join('')}`).join('')||'<tr><td colspan="3" class="compare-empty">Keine Kriterien für diesen Filter. Wähle «Alle», um weiterzuarbeiten.</td></tr>';}
function comparison(){const label=concept==='matrix'?'Was macht den Unterschied?':'Deine Favoriten. Im direkten Vergleich.';return `<section class="comparison-main"><div class="comparison-heading"><div><h1>${label}</h1><p>Vergleiche deine Anforderungen. Ergänze fehlende Angaben direkt im Vergleich.</p></div>${btn(icon('car')+' Auto erfassen','add','','primary')}</div><div class="comparison-tools"><nav class="comparison-tabs" aria-label="Vergleichsinhalt"><button data-action="compare-tab" data-tab="criteria" class="${state.compareTab==='criteria'?'active':''}" aria-pressed="${state.compareTab==='criteria'}">Kriterien</button><button data-action="compare-tab" data-tab="specs" class="${state.compareTab==='specs'?'active':''}" aria-pressed="${state.compareTab==='specs'}">Technische Daten</button></nav>${state.compareTab==='criteria'?filters(true):'<span class="demo-note">Technische Daten werden nicht bewertet.</span>'}</div><p class="comparison-scroll-hint">Seitlich wischen, um beide Autos zu sehen.</p><div class="comparison-scroll" role="region" aria-label="Fahrzeugvergleich, seitlich scrollbar" tabindex="0"><table class="comparison-table"><thead><tr><th class="comparison-label" scope="col"><strong>${state.compareTab==='criteria'?'Deine Anforderungen':'Technische Daten'}</strong>${state.compareTab==='criteria'?'Werte anklicken und bearbeiten':'Fakten nebeneinander'}</th><th scope="col">${compareSelect(state.car,'first')}</th><th scope="col">${compareSelect(state.second,'second')}</th></tr></thead><tbody>${comparisonRows()}</tbody></table></div><div class="comparison-footer"><p>Unbekannt ist kein Nein. Persönliche Bewertungen bleiben subjektiv. Ein verfehltes Muss führt nicht zum automatischen Ausschluss.</p><span class="scroll-hint">${btn('Zum Fahrzeug '+icon('arrow'),'navigate','data-view="capture"','text')}</span></div></section>`;}
function criteriaView(){return `<section class="record"><div class="record-heading"><div><h1>Was ist dir wichtig?</h1><p class="record-subtitle">Anforderungen für alle Autos dieser Evaluation.</p></div></div><p class="criteria-help">Dieselben Gruppen und Prioritäten erscheinen beim Erfassen und Vergleichen. Diese Konzeptansicht zeigt die gemeinsame Struktur.</p>${criteria.map(cr=>`<div class="assessment-row" style="grid-template-columns:1fr 1fr 100px"><span class="criterion-title">${cr.name}<small>${cr.group}</small></span><span class="muted">${cr.hint}</span>${priority(cr)}</div>`).join('')}<p class="record-bottom-note">Kriterien anlegen, gruppieren und sortieren bleiben im späteren Ausbau erhalten. In dieser Vorschau werden Fahrzeugbewertungen bearbeitet.</p></section>`;}
function financeView(){return `${candidateRibbon()}<section class="record finance-record"><h1>Deine Offerten</h1><p class="record-subtitle">Angebote und Unterlagen beim jeweiligen Auto.</p>${offers()}</section>`;}
function render(){if(!concept){gallery();return}document.documentElement.lang='de';document.title=`Steervo · ${directions[concept].name}`;const content=state.view==='capture'?capture():state.view==='compare'?comparison():state.view==='criteria'?criteriaView():financeView();app.innerHTML=`${embedded?'':reviewBar()}<div class="product ${concept}">${concept==='workspace'?`${sidebar()}<div class="work-area">${context()}<main id="main" tabindex="-1">${content}</main></div>`:`${topNav()}<main id="main" tabindex="-1" class="${concept==='dossier'?'dossier-main-wrap':'matrix-main'}">${context()}<div class="${concept==='dossier'?'dossier-main':''}">${content}</div></main>`}</div>${embedded?'':`<div class="review-note"><strong>${directions[concept].letter} · ${directions[concept].name}</strong><span>${directions[concept].summary}</span><button class="plain-link" data-action="reset">Demo zurücksetzen</button></div>`}${state.editor&&!(concept==='dossier'&&state.editor.kind==='assessment')?drawer():''}`;document.body.classList.toggle('editing',!!document.querySelector('.editor-panel'));if(embedded)document.querySelector('.product').style.minHeight='960px';}
function assessmentFields(cr,record){let input;if(cr.type==='number')input=`<input id="edit-value" name="value" type="number" min="0" step="any" value="${esc(record.value)}" placeholder="Noch offen" inputmode="decimal"><small>Leeres Feld = unbekannt · ${cr.unit}</small>`;else{const choices=cr.type==='boolean'?['Ja','Nein']:['1','2','3','4','5'];input=`<select id="edit-value" name="value"><option value="">Noch offen</option>${choices.map(v=>`<option value="${v}" ${record.value===v?'selected':''}>${v}${cr.type==='rating'?' / 5':''}</option>`).join('')}</select>`;}return `<div class="field-grid"><div class="field"><label for="edit-value">Deine Angabe${cr.unit?' ('+cr.unit+')':''}</label>${input}</div><div class="field"><label for="edit-source">Grundlage</label><select name="source" id="edit-source">${['Noch offen','Herstellerangabe','Offerte','Probefahrt','Eigene Recherche'].map(s=>`<option ${record.source===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="field notes-field"><label for="edit-notes">Notiz <span class="muted">(optional)</span></label><textarea id="edit-notes" name="notes" rows="3" placeholder="Was möchtest du dazu festhalten?">${esc(record.notes||'')}</textarea></div>`;}
function editorForm(inline=false){const e=state.editor,cr=criteria.find(c=>c.id===e.criterion),car=carById(e.car);return `<section class="${inline?'inline-editor':''}" ${inline?'role="region" aria-label="Bewertung bearbeiten"':''}><div class="editor-heading"><div><h2 id="editor-title">${cr.name}</h2><p>${esc(car.name)} · Bewertung bearbeiten</p></div><button class="icon-button" data-action="close-editor" aria-label="Bearbeitung schliessen">${icon('close')}</button></div><div class="editor-context">${priority(cr)}<span>${cr.hint}</span></div><form id="editor-form" class="editor-form" data-form="assessment">${assessmentFields(cr,getValue(e.car,e.criterion))}<div class="editor-actions">${btn('Abbrechen','close-editor')}<button class="button primary" type="submit">${icon('check')} Speichern</button></div></form>${inline?'':'<p class="demo-note">Die Änderung erscheint auch im Fahrzeug und im Vergleich. Nur in diesem Browser-Tab gespeichert.</p>'}</section>`;}
function textField(label,name,value='',required=false){return `<div class="field"><label for="form-${name}">${label}</label><input id="form-${name}" name="${name}" value="${esc(value)}" ${required?'required maxlength="80"':'maxlength="200"'}></div>`;}
function otherEditor(){const e=state.editor,car=carById(e.car||state.car);let title,fields;if(e.kind==='add'||e.kind==='car'){title=e.kind==='add'?'Auto erfassen':'Stammdaten bearbeiten';const c=e.kind==='add'?{}:car;fields=textField('Name des Autos','name',c.name,true)+textField('Variante / Ausstattung','trim',c.trim)+`<div class="field-grid">${textField('Jahr','year',c.year)}${textField('Kilometerstand','mileage',c.mileage)}</div>`+(e.kind==='car'?`<div class="field"><label for="form-status">Einordnung</label><select id="form-status" name="status"><option ${c.status==='In Auswahl'?'selected':''}>In Auswahl</option><option ${c.status==='Favorit'?'selected':''}>Favorit</option></select><small>Zurückstellen und Ausscheiden mit Begründung folgen im späteren Ausbau.</small></div>`:'');}else if(e.kind==='notes'){title='Notiz bearbeiten';fields=`<div class="field"><label for="form-note">Dein Eindruck zu ${esc(car.name)}</label><textarea id="form-note" name="note" rows="7" maxlength="2000">${esc(car.note)}</textarea></div>`;}else{title='Technische Daten';fields=['Länge (mm)','Breite ohne Spiegel (mm)','Sitzplätze','Batterie netto (kWh)'].map((label,i)=>textField(label,'spec'+i,car.specs[i])).join('');}return `<div class="editor-heading"><div><h2 id="editor-title">${title}</h2><p>${e.kind==='add'?'Familienauto 2026':esc(car.name)}</p></div><button class="icon-button" data-action="close-editor" aria-label="Bearbeitung schliessen">${icon('close')}</button></div><form id="editor-form" data-form="${e.kind}">${fields}<div class="editor-actions">${btn('Abbrechen','close-editor')}<button type="submit" class="button primary">${e.kind==='add'?'Auto hinzufügen':'Speichern'}</button></div></form><p class="demo-note">Beispieldaten · Änderungen bleiben in diesem Browser-Tab.</p>`;}
function drawer(){return `<div class="editor-shade" data-action="close-editor"></div><section class="editor-panel ${concept}" role="dialog" aria-modal="true" aria-labelledby="editor-title">${state.editor.kind==='assessment'?editorForm():otherEditor()}</section>`;}
function focusEditor(){requestAnimationFrame(()=>{const editor=document.querySelector('.editor-panel,.inline-editor');editor?.querySelector('input,select,textarea')?.focus({preventScroll:true});if(concept==='dossier'&&state.editor?.kind==='assessment')editor?.scrollIntoView({block:'nearest',behavior:'instant'});});}
function closeEditor(){state.editor=null;render();if(lastFocus){const focus=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===lastFocus.action&&(!lastFocus.criterion||el.dataset.criterion===lastFocus.criterion)&&(!lastFocus.car||el.dataset.car===lastFocus.car));focus?.focus({preventScroll:true});}}
function setEditor(editor,element){lastFocus={...element.dataset};state.editor=editor;render();focusEditor();}
app.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='reset'){cars=structuredClone(initialCars);values=structuredClone(initialValues);state={...state,car:cars[0].id,second:cars[1].id,editor:null,filter:'all'};persist();render();toast('Beispieldaten zurückgesetzt');return;}if(action==='close-editor'){closeEditor();return;}if(action==='edit'){setEditor({kind:'assessment',car:el.dataset.car,criterion:el.dataset.criterion},el);return;}if(['add','edit-car','edit-notes','edit-specs'].includes(action)){setEditor({kind:action.replace('edit-',''),car:state.car},el);return;}state.editor=null;if(action==='navigate'){state.view=el.dataset.view;state.filter='all';}else if(action==='select-car'){const previous=state.car;state.car=el.dataset.car;if(state.car===state.second)state.second=previous;}else if(action==='tab')state.tab=el.dataset.tab;else if(action==='filter')state.filter=el.dataset.filter;else if(action==='compare-tab')state.compareTab=el.dataset.tab;else if(action==='offer')state.offer=!state.offer;render();const target=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===action&&(el.dataset.filter?x.dataset.filter===el.dataset.filter:el.dataset.tab?x.dataset.tab===el.dataset.tab:el.dataset.car?x.dataset.car===el.dataset.car:el.dataset.view?x.dataset.view===el.dataset.view:true));target?.focus({preventScroll:true});});
app.addEventListener('change',event=>{const side=event.target.dataset.compare;if(side){state[side==='first'?'car':'second']=event.target.value;state.editor=null;render();document.querySelector(`#compare-${side}`)?.focus();}});
app.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-form]'))return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),e=state.editor;const car=carById(e.car||state.car);if(e.kind==='assessment'){values[e.car]??={};values[e.car][e.criterion]={value:data.value,source:data.source,notes:data.notes};}else if(e.kind==='add'){const id='demo-'+Date.now();cars.push({id,name:data.name.trim(),trim:data.trim.trim()||'Variante offen',year:data.year||'Jahr offen',mileage:data.mileage||'Offen',status:'In Auswahl',note:'',specs:['','','',''],price:null});values[id]={};state.car=id;state.view='capture';state.tab='criteria';state.filter='all';}else if(e.kind==='car'){Object.assign(car,{name:data.name.trim(),trim:data.trim.trim(),year:data.year,mileage:data.mileage,status:data.status});}else if(e.kind==='notes'){car.note=data.note;}else if(e.kind==='specs'){car.specs=[data.spec0,data.spec1,data.spec2,data.spec3];}persist();closeEditor();toast(e.kind==='add'?'Auto zur Auswahl hinzugefügt':'Gespeichert · Fahrzeug und Vergleich sind aktuell');});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.editor){event.preventDefault();closeEditor();return;}if(event.key==='Tab'){const panel=document.querySelector('.editor-panel');if(!panel)return;const items=[...panel.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
render();
